import { defineConfig, devices } from "@playwright/test";

/**
 * Browser truth table for the in-page signals (Phase 0). The fixture server
 * (server.mjs) serves the page generated by the real instrumenter and logs
 * every /_s request with the headers that matter. Run:
 *
 *   npm run fixture && npx playwright install chromium firefox webkit && npm test
 *
 * Results are written to results/<project>.json; docs/browser-matrix.md is
 * derived from them.
 */
export default defineConfig({
  testDir: ".",
  testMatch: /matrix\.spec\.ts/,
  timeout: 60_000,
  retries: 0,
  workers: 1,
  reporter: [["list"]],
  use: { baseURL: "http://127.0.0.1:4789", headless: true },
  webServer: { command: "node server.mjs", port: 4789, reuseExistingServer: true },
  projects: [
    { name: "chromium", use: { ...devices["Desktop Chrome"] } },
    { name: "firefox", use: { ...devices["Desktop Firefox"] } },
    { name: "webkit", use: { ...devices["Desktop Safari"] } },
    { name: "chrome", use: { ...devices["Desktop Chrome"], channel: "chrome" } },
  ],
});
